# Generated by build.py from recipe.yml for recipe mqtt5-subscribe-over-websocket. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"dash/#;retain"', '--mqtt5-disconnect-after-retained', 'mqtt5://127.0.0.1:8080/', 'mqtt5+ws://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -d 21 mqtt5://127.0.0.1:8080/dash/temp --next -sS mqtt5+ws://127.0.0.1:8081/dash/temp } finally { Stop-Process $server0 }
